changeSet.sql:
ALTER TABLE promotions.promo_code
ADD CONSTRAINT chk_promo_code_status
CHECK (status IN ('AVAILABLE','ISSUED','REDEEMED','EXPIRED','VOID'));

ALTER TABLE promotions.promo_code
ADD CONSTRAINT chk_promo_code_code_length
CHECK (char_length(code) <= 32);

ALTER TABLE promotions.promo_code
ADD CONSTRAINT chk_promo_code_booking_ref_length
CHECK (booking_reference IS NULL OR char_length(booking_reference) <= 64);

DROP TRIGGER IF EXISTS promo_code_touch_updated_at ON promotions.promo_code;
CREATE TRIGGER promo_code_touch_updated_at
BEFORE UPDATE ON promotions.promo_code
FOR EACH ROW
EXECUTE FUNCTION promotions.touch_updated_at();

CREATE INDEX IF NOT EXISTS idx_promo_code_batch_id
ON promotions.promo_code(batch_id);

CREATE INDEX IF NOT EXISTS idx_promo_code_status
ON promotions.promo_code(status);

CREATE INDEX IF NOT EXISTS idx_promo_code_booking_reference
ON promotions.promo_code(booking_reference);
